widget.solution:
from math import erf, exp, log, sqrt, pi

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def norm_pdf(z):
    return exp(-z * z / 2) / sqrt(2 * pi)

def pde_terms(S, K, r, sigma, T):
    d1 = (log(S / K) + (r + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    V = S * norm_cdf(d1) - K * exp(-r * T) * norm_cdf(d2)
    delta = norm_cdf(d1)
    gamma = norm_pdf(d1) / (S * sigma * sqrt(T))
    theta = -S * norm_pdf(d1) * sigma / (2 * sqrt(T)) - r * K * exp(-r * T) * norm_cdf(d2)
    t1, t2, t3, t4 = theta, r * S * delta, 0.5 * sigma ** 2 * S ** 2 * gamma, r * V
    return [t1, t2, t3, t4, t1 + t2 + t3 - t4]
